import { formatDate } from '@angular/common';
import { Component } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ActivatedRoute } from '@angular/router';
import { ClaimKey } from '../../constant/constant';
import { isAllEmptyOrNull, isNullOrEmpty } from '../../core/commonFunction/common-function';
import { TableColumn } from '../../core/component/data-table/data-table.component';
import { LocalStorageService } from '../../core/local-storage.service';
import { NotificationService } from '../../core/notificationService/notification-service';
import { BankAccountService } from '../../core/service/bank-account.service';
import { DropDownDto } from '../../dto/internal-dto/drop-down-dto';
import { ResponseDto } from '../../dto/internal-dto/response-dto';
import { TransactionsListAccountInfoDto } from '../../dto/internal-dto/transactions-list-account-info-dto';
import { GetAccountTypeDropDownListRequestObject } from '../../dto/request/bank-account/get-account-type-drop-down-list-request';
import { createTransactionListRequestObject } from '../../dto/request/bank-account/transaction-list-request';
import { TransactionsListForCustomerRequestObject } from '../../dto/request/bank-account/transactions-list-for-customer-request';
import { GetTransactionsListResponse, GetTransactionsListResponseCardInfo, GetTransactionsListResponseTransactionList } from '../../dto/response/get-transactions-list-response';

@Component({
  selector: 'app-transactions-list',
  templateUrl: './transactions-list.component.html',
  styleUrls: ['./transactions-list.component.css']
})
export class TransactionsListComponent {
  columns: TableColumn[] = [
    { field: 'fromAccountId', header: 'Transfer From', sortable: true, width: '13%' },
    { field: 'toAccountId', header: 'Transfer To', sortable: true, width: '13%' },
    { field: 'transactionCategory', header: 'Category', sortable: true, width: '10%' },
    { field: 'transactionTag', header: 'Tag', sortable: true, width: '8%' },
    { field: 'transactionDate', header: 'Date', sortable: true, width: '11%', format: 'date', dateFormat: 'dd/MM/yyyy' },
    { field: 'description', header: 'Description', width: '18%' },
    { field: 'creditAmount', header: 'Credit', format: 'currency', sortable: true, width: '8%' },
    { field: 'debitAmount', header: 'Debit', format: 'currency', sortable: true, width: '8%' },
    { field: 'stageBalance', header: 'Stage Balance', format: 'currency', sortable: true, width: '12%' }
  ];

  transactionForm: FormGroup;
  transactionFilterForm: FormGroup;
  bankList: DropDownDto[] = [];
  accountTypeList: DropDownDto[] = [];
  transactionCategoryList: DropDownDto[] = [];
  transactionTagList: DropDownDto[] = [];
  senderAccountList: DropDownDto[] = [];
  receiverAccoountList: DropDownDto[] = [];
  customerId: number = 0;
  accountInfo: TransactionsListAccountInfoDto | null = null;
  cardInfo: GetTransactionsListResponseCardInfo[] = [];
  transactionsList: GetTransactionsListResponseTransactionList[] = [];
  get accountTypeId(): number {
    return this.transactionForm.controls["accountTypeId"].value;
  }
  get bankId(): number {
    return this.transactionForm.controls["bankId"].value;
  }
  get fromDate(): Date {
    return this.transactionFilterForm.controls["fromDate"].value;
  }
  set fromDate(value: Date | null) {
    this.transactionFilterForm.patchValue({ fromDate: value == null ? null : this.formatDateForInput(value) });
  }
  get toDate(): Date {
    return this.transactionFilterForm.controls["toDate"].value;
  }
  set toDate(value: Date | null) {
    this.transactionFilterForm.patchValue({ toDate: value == null ? null : this.formatDateForInput(value) });
  }
  constructor(private readonly activatedRoute: ActivatedRoute, private fb: FormBuilder, private bankAccountService: BankAccountService,
    private localStorageService: LocalStorageService, private notificationService: NotificationService) {
    this.transactionForm = this.fb.group({
      bankId: ['', [Validators.required]],
      accountTypeId: ['', [Validators.required]]
    });
    this.transactionFilterForm = this.fb.group({
      fromDate: [''],
      toDate: [''],
      category: [''],
      transactionTag: [''],
      senderAccountId: [''],
      receiverAccountId: [''],
    });
    let yesterday = new Date();
    yesterday.setDate(new Date().getDate() - 7);
    this.transactionFilterForm.patchValue({
      fromDate: this.formatDateForInput(yesterday),
      toDate: this.formatDateForInput(new Date()),
    });
  }
  ngOnInit() {
    const initialData: ResponseDto<boolean> = this.activatedRoute.snapshot.data['DataResolver'];
    if (initialData.status == false) {
      let messageList: string[] = [];
      if (Array.isArray(initialData?.errors) && initialData?.errors)
        messageList = [...initialData?.errors?.map(x => x.errorMessage), ...initialData?.validationErrors?.map(x => x.errorMessage)]
      messageList.push("Transaction list page load failed.");
      messageList.forEach((msg) => {
        this.notificationService.show(msg, 'error')
      });
    }
    this.bankList = initialData.dropDownList.find(x => x.name == "Bank")!.dropDown;

    this.customerId = Number(this.localStorageService.getItem(ClaimKey.customerId));

    this.transactionForm.get('bankId')?.valueChanges.subscribe(bankId => {
      if (!isNullOrEmpty(bankId) && !isNullOrEmpty(this.customerId)) {
        let model: GetAccountTypeDropDownListRequestObject = {
          request: {
            bank: {
              id: bankId
            },
            customer: {
              id: this.customerId
            }
          }
        }
        this.bankAccountService.getAccountTypeDropDownListByCustomerIdAndBankId(model).subscribe((response: ResponseDto<boolean>) => {
          if (response.status == true) {
            this.accountTypeList = response.dropDownList.find(x => x.name == "AccountType")!.dropDown;
            if (this.accountTypeList.length == 1) {
              this.transactionForm.controls["accountTypeId"].setValue(this.accountTypeList[0].key);
            }
            else
              this.transactionForm.controls["accountTypeId"].setValue('');
          } else {
            let messageList: string[] = [];
            if (Array.isArray(response?.errors) && response?.errors)
              messageList = [...response?.errors?.map(x => x.errorMessage), ...response?.validationErrors?.map(x => x.errorMessage)]
            messageList.push("Get Account Type Drop Down failed.");
            messageList.forEach((msg) => {
              this.notificationService.show(msg, 'error');
            });
          }
        });
      }
      else {
        this.transactionForm.controls["accountTypeId"].setValue('');
      }
    });
    this.transactionForm.get('accountTypeId')?.valueChanges.subscribe(accountTypeId => {
      if (!isNullOrEmpty(accountTypeId) && !isNullOrEmpty(this.bankId) && !isNullOrEmpty(this.customerId)) {
        let model: TransactionsListForCustomerRequestObject = {
          request: {
            account: {
              accountTypeId: this.accountTypeId
            },
            bank: {
              id: this.bankId
            },
            customer: {
              id: this.customerId
            }
          }
        }
        this.bankAccountService.transactionsListForCustomer(model).subscribe((response: ResponseDto<GetTransactionsListResponse>) => {
          if (response.status == true) {
            this.accountInfo = response.response.accountInfo;
            this.cardInfo = response.response.cardInfo;
            this.transactionsList = response.response.transactionsList.map(trans => ({
              ...trans,
              creditAmount: trans.transactionType === 'Credit' ? trans.amount : '',
              debitAmount: trans.transactionType === 'Debit' ? trans.amount : ''
            }));
            this.transactionCategoryList = response.dropDownList.find(x => x.name == "TransactionCategory")!.dropDown;
            this.transactionTagList = response.dropDownList.find(x => x.name == "TransactionTag")!.dropDown;
            this.senderAccountList = response.dropDownList.find(x => x.name == "SenderAccount")!.dropDown;
            this.receiverAccoountList = response.dropDownList.find(x => x.name == "ReceiverAccount")!.dropDown;
          } else {
            let messageList: string[] = [];
            if (Array.isArray(response?.errors) && response?.errors)
              messageList = [...response?.errors?.map(x => x.errorMessage), ...response?.validationErrors?.map(x => x.errorMessage)]
            messageList.push("Get transactions list failed.");
            messageList.forEach((msg) => {
              this.notificationService.show(msg, 'error');
            });
          }
        });
      }
    });
  }
  getTransactionList() {
    let values = this.transactionFilterForm.value;
    if (!isNullOrEmpty(this.accountInfo!.accountId)) {
      let model = createTransactionListRequestObject(this.accountInfo!.accountId, values.receiverAccountId, values.senderAccountId, values.category,
        this.fromDate, values.transactionTag, this.toDate);
      this.bankAccountService.transactionList(model).subscribe((response: ResponseDto<GetTransactionsListResponse>) => {
        if (response.status == true) {
          this.transactionsList = response.response.transactionsList.map(trans => ({
            ...trans,
            creditAmount: trans.transactionType === 'Credit' ? trans.amount : '',
            debitAmount: trans.transactionType === 'Debit' ? trans.amount : ''
          }));
        } else {
          let messageList: string[] = [];
          if (Array.isArray(response?.errors) && response?.errors)
            messageList = [...response?.errors?.map(x => x.errorMessage), ...response?.validationErrors?.map(x => x.errorMessage)]
          messageList.push("Get transactions list failed.");
          messageList.forEach((msg) => {
            this.notificationService.show(msg, 'error');
          });
        }
      });
    }
  }
  setFromDate($event: any) {
    $event.preventDefault();
    if (!isNullOrEmpty($event.target.value))
      this.fromDate = new Date($event.target.value);
    else
      this.fromDate = null;
  }
  setToDate($event: any) {
    $event.preventDefault();
    if (!isNullOrEmpty($event.target.value))
      this.toDate = new Date($event.target.value);
    else
      this.toDate = null;
  }
  formatDateForInput(date: Date): string {
    return formatDate(date, 'yyyy-MM-dd', 'en');
  }
}
